// Schlecht: ein grobes Objekt-Signal, jede Änderung betrifft alle Leser
state = signal({ customers: [], filter: '', selectedId: null });

// Besser: feine Signals und computed, nur betroffene Leser werden aktualisiert
customers  = signal<Customer[]>([]);
filter     = signal('');
selectedId = signal<string | null>(null);
selected   = computed(() => this.customers().find(c => c.id === this.selectedId()));

// computed meldet nur dann eine Änderung, wenn sich sein Ergebnis wirklich ändert.
// Leser von selected werden also nicht geprüft, wenn sich nur der Filter ändert.

// Eingabefeld zeigt typedFilter sofort, der Store bekommt den Text verzögert
protected readonly typedFilter = signal(this.store.filter());

constructor() {
  toObservable(this.typedFilter).pipe(
    debounceTime(250),        // erst nach 250 ms Ruhe weitergeben
    takeUntilDestroyed()      // beim Zerstören der Komponente abmelden
  ).subscribe(text => this.store.setFilter(text));
}

onFilterChanged(text: string) {
  this.typedFilter.set(text);
}
onFilterCleared() {            // Leeren wirkt sofort, ohne Wartezeit
  this.typedFilter.set('');
  this.store.setFilter('');
}

